svg.script:
(() => {
  const svg = document.currentScript.ownerSVGElement;
  const pupils = Array.from(svg.querySelectorAll('.pupil'));
  const eyes = pupils.map(node => ({
    node,
    x: Number(node.getAttribute('cx')),
    y: Number(node.getAttribute('cy'))
  }));
  let pendingFrame = 0;
  let pointer = null;

  function paint() {
    pendingFrame = 0;
    const matrix = svg.getScreenCTM();
    if (!pointer || !matrix) return;
    const point = svg.createSVGPoint();
    point.x = pointer.x;
    point.y = pointer.y;
    const local = point.matrixTransform(matrix.inverse());
    for (const eye of eyes) {
      const dx = local.x - eye.x;
      const dy = local.y - eye.y;
      // Smoothly limit travel so the pupils stay inside the cream panels.
      const distance = Math.hypot(dx, dy, 100);
      eye.node.style.transform = `translate(${9 * dx / distance}px, ${7 * dy / distance}px)`;
    }
  }

  function reset() {
    pointer = null;
    cancelAnimationFrame(pendingFrame);
    pendingFrame = 0;
    for (const eye of eyes) eye.node.style.transform = 'translate(0px, 0px)';
  }

  document.addEventListener('pointermove', event => {
    if (event.pointerType === 'touch') return;
    pointer = {x: event.clientX, y: event.clientY};
    if (!pendingFrame) pendingFrame = requestAnimationFrame(paint);
  }, {passive: true});
  document.documentElement.addEventListener('pointerleave', reset);
  window.addEventListener('blur', reset);
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) reset();
  });
})();
